CREATE OR ALTER FUNCTION [dbo].[GetAssetTypeIconById] ( @Id bigint ) RETURNS @icons TABLE ( Id bigint, [Object] varchar(50), Objectid int, Icon varchar(50) ) AS begin
declare @object varchar(50), @defaultIcon varchar(50);
declare @nav table (ID int, ParentID int, Object varchar(50), ObjectID int, Icon varchar(50), AssetTypeID bigint);
select @object = T.[Object], @defaultIcon = N.Icon from AssetType T left join SiteNav N on N.[Name] = case when T.Class = 1 then '#Business' when T.Class in (3,4) then '#Fusion' when T.Class = 2 then '#Models' when T.Class = 6 then '#Policy' when T.Class in (9,14) then '#Reference' when T.Class = 7 then '#Data Quality' when T.Class = 8 then '#Technical' else null end where T.ID = @Id;
;with Nav as ( select ID, ParentID, [Object], ObjectID, Icon from SiteNav N where ParentID is null and (N.Object = @object or N.Object is null)
union all
select S.ID, S.ParentID, S.[Object], S.ObjectID, N.Icon from SiteNav S inner join Nav N on N.ID = S.ParentID ) insert into @nav select N.ID, N.ParentID, N.[Object], N.ObjectID, N.Icon, T.ID as AssetTypeID from Nav N inner join AssetType T on T.[Object] = N.[Object] and T.ObjectID = N.ObjectID where N.ObjectID is not null;
;with childNavItems as ( select T.ID, C.ID as ChildID, N.Icon from AssetType T inner join @nav N on N.Object = T.Object and N.ObjectID = T.ObjectID inner join IntersectTypeDetail I on I.Subject = T.Object and I.SubjectID = T.ObjectID and I.PredicateType in (3, 4) inner join AssetType C on C.Object = I.Object and C.ObjectID = I.ObjectID
union all
select T.ID, C.ID as ChildID, R.Icon from AssetType T inner join childNavItems R on R.ChildID = T.ID inner join IntersectTypeDetail I on I.Subject = T.Object and I.SubjectID = T.ObjectID and I.PredicateType in (3, 4) inner join AssetType C on C.Object = I.Object and C.ObjectID = I.ObjectID where C.ID <> T.ID ) insert into @icons select T.ID, T.Object, T.ObjectID, coalesce(S.Icon, N.Icon, R.Icon, @defaultIcon) as Icon from AssetType T left join AssetTypeStyle S on S.ID = T.ID and S.Icon <> '' left join @nav N on N.Object = T.Object and N.ObjectID = T.ObjectID left join childNavItems R on R.ChildID = T.ID where T.ID = @Id;
return
end
